import re

def solve(env, goal):
    def get_obs():
        return env.observation

    # Determine target object and final receptacle from goal
    m = re.search(r'(?:put|place|move)\s+(?:some|a|an|the)?\s*(.+?)\s+(?:in|into|to)\s+(.+?)(?:[.,]|$)', goal, re.I)
    if m:
        obj_phrase = m.group(1).strip()
        final_rec = m.group(2).strip()
    else:
        words = re.findall(r'\w+(?:\s+\d+)?', goal)
        obj_phrase = words[0] if words else ''
        final_rec = words[-1] if words else ''

    obj = re.sub(r'^(?:a|an|the|some)\s+', '', obj_phrase, flags=re.I).strip()

    def obj_base(o):
        return re.sub(r'\s+\d+$', '', o).strip().lower()

    obj_b = obj_base(obj)

    # Determine action from goal
    g = goal.lower()
    action = None
    for kw, act in [('heat', 'heat'), ('warm', 'heat'), ('cook', 'heat'),
                   ('clean', 'clean'), ('wash', 'clean'),
                   ('slice', 'slice'), ('chop', 'slice')]:
        if kw in g:
            action = act
            break

    # State variables
    holding = None
    current_loc = None
    visited = set()
    steps = 0

    def step(cmd):
        nonlocal steps
        steps += 1
        return env.step(cmd)

    def parse_holding(obs):
        m = re.search(r'You pick up the (.+?)\.', obs, re.I)
        if m:
            return m.group(1).strip()
        return None

    def parse_location(obs):
        m = re.search(r'You arrive at (.+?)\.', obs, re.I)
        if m:
            return m.group(1).strip()
        return None

    def visible_objects(obs):
        objs = []
        # Find text after "you see" or "In it, you see"
        for m in re.finditer(r'(?:you see|In it, you see|On the \w+(?: \w+)?, you see)([^.\n]*)', obs, re.I):
            part = m.group(1)
            for item in re.split(r',| and ', part):
                item = item.strip().rstrip('.')
                item = re.sub(r'^(?:a|an|the)\s+', '', item, flags=re.I)
                if item and item.lower() not in ('nothing', 'it', 'a', 'an'):
                    objs.append(item)
        return objs

    def obj_matches(o, target):
        ob = obj_base(o)
        tb = obj_base(target)
        if ob != tb:
            return False
        on = re.search(r'\s+(\d+)$', o)
        tn = re.search(r'\s+(\d+)$', target)
        if on and tn and on.group(1) != tn.group(1):
            return False
        return True

    # Parse initial room for receptacles
    room_obs = get_obs()
    receptacles = re.findall(r'\b([a-z]+(?:\s+[a-z]+)?\s+\d+)\b', room_obs)
    receptacles = [r.strip() for r in receptacles]
    # Deduplicate preserving order
    seen = set()
    uniq_recs = []
    for r in receptacles:
        if r.lower() not in seen:
            seen.add(r.lower())
            uniq_recs.append(r)
    receptacles = uniq_recs

    def take_object(loc, o):
        nonlocal holding
        fb = step(f'take {o} from {loc}' if loc else f'take {o}')
        h = parse_holding(fb)
        if h:
            holding = h
            return True
        return False

    # 1. Find the object
    # Check current observation first
    objs = visible_objects(get_obs())
    for o in objs:
        if obj_matches(o, obj):
            if take_object(None, o):
                break

    # Search receptacles
    if not holding:
        for rec in receptacles:
            if steps >= 40:
                break
            if rec.lower() in visited:
                continue
            fb = step(f'go to {rec}')
            loc = parse_location(fb)
            if loc:
                current_loc = loc
                visited.add(loc.lower())
            else:
                current_loc = rec
                visited.add(rec.lower())
            # open if closed
            if 'closed' in fb.lower():
                fb = step(f'open {rec}')
                loc2 = parse_location(fb)
                if loc2:
                    current_loc = loc2
            objs = visible_objects(fb)
            for o in objs:
                if obj_matches(o, obj):
                    if take_object(current_loc, o):
                        break
            if holding:
                break

    # 2. Perform action
    if holding and action:
        if action == 'heat':
            # Need to open microwave and heat
            fb = step('go to microwave 1')
            loc = parse_location(fb)
            if loc:
                current_loc = loc
                visited.add(loc.lower())
            if 'closed' in fb.lower():
                fb = step('open microwave 1')
                loc = parse_location(fb)
                if loc:
                    current_loc = loc
            fb = step(f'heat {holding} with microwave 1')
        elif action == 'clean':
            fb = step('go to sinkbasin 1')
            loc = parse_location(fb)
            if loc:
                current_loc = loc
                visited.add(loc.lower())
            if 'closed' in fb.lower():
                fb = step('open sinkbasin 1')
            fb = step(f'clean {holding} with sinkbasin 1')
            if not ('clean' in fb.lower() or 'wash' in fb.lower()):
                # try again with same basin name
                fb = step(f'clean {holding} with sinkbasin 1')
        elif action == 'slice':
            # try knife or just slice
            fb = step(f'slice {holding}')

    # 3. Put in final receptacle
    if holding:
        fb = step(f'go to {final_rec}')
        loc = parse_location(fb)
        if loc:
            current_loc = loc
            visited.add(loc.lower())
        if 'closed' in fb.lower():
            fb = step(f'open {final_rec}')
            loc = parse_location(fb)
            if loc:
                current_loc = loc
        fb = step(f'move {holding} to {final_rec}')
        if 'move' in fb.lower() or 'put' in fb.lower():
            holding = None

    return None
