import re

def solve(env, goal):
    def get_obs():
        return env.observation

    # Parse goal: "heat some tomato and put it in fridge."
    # or "clean a apple and put it in fridge."
    # or "put a clean apple in fridge."
    action = None
    g = goal.lower()
    for kw, act in [('heat', 'heat'), ('warm', 'heat'), ('cook', 'heat'),
                   ('clean', 'clean'), ('wash', 'clean'),
                   ('slice', 'slice'), ('chop', 'slice'),
                   ('freeze', 'freeze'), ('chill', 'freeze')]:
        if kw in g:
            action = act
            break

    # Find object phrase: between action and "and put" or after "put"
    m = re.search(r'(?:heat|warm|cook|clean|wash|slice|chop|freeze|chill)\s+(?:some|a|an|the)?\s*(.+?)\s+and\s+put\s+it\s+(?:in|into|to)\s+(.+?)(?:[.,]|$)', goal, re.I)
    if m:
        obj_phrase = m.group(1).strip()
        final_rec = m.group(2).strip()
    else:
        m2 = re.search(r'put\s+(?:some|a|an|the)?\s*(.+?)\s+(?:in|into|to)\s+(.+?)(?:[.,]|$)', goal, re.I)
        if m2:
            obj_phrase = m2.group(1).strip()
            final_rec = m2.group(2).strip()
        else:
            words = re.findall(r'\w+(?:\s+\d+)?', goal)
            obj_phrase = words[0] if words else ''
            final_rec = words[-1] if words else ''

    # Strip leading articles and adjectives like "clean", "hot"
    def clean_obj_name(s):
        s = re.sub(r'^(?:a|an|the|some|clean|hot|heated|warm|cold|sliced)\s+', '', s, flags=re.I)
        s = re.sub(r'\s+(?:clean|hot|heated|warm|cold|sliced)$', '', s, flags=re.I)
        return s.strip()

    obj = clean_obj_name(obj_phrase)
    obj_b = re.sub(r'\s+\d+$', '', obj).strip().lower()

    def obj_base(o):
        return re.sub(r'\s+\d+$', '', o).strip().lower()

    def obj_matches(o, target):
        ob = obj_base(o)
        tb = obj_base(target)
        if ob != tb:
            return False
        on = re.search(r'\s+(\d+)$', o)
        tn = re.search(r'\s+(\d+)$', target)
        if on and tn and on.group(1) != tn.group(1):
            return False
        return True

    # Parse initial room for receptacles (strip leading articles)
    room_obs = get_obs()
    raw_recs = re.findall(r'\b((?:[a-z]+\s+)?[a-z]+\s+\d+)\b', room_obs)
    # Better: find all "word number" where word is a known receptacle-ish noun
    # Use pattern of lowercase words followed by number
    raw_recs = re.findall(r'\b([a-z][a-z]*\s+\d+)\b', room_obs)
    # But multiword receptacles like "coffeemachine 1" are single token; "stoveburner 4" single
    # Actually "coffeemachine" is one word. "sinkbasin" one word. So single-word + number works.
    # But "diningtable 1" is one word. Good.
    receptacles = []
    seen = set()
    for r in raw_recs:
        if r.lower() not in seen:
            seen.add(r.lower())
            receptacles.append(r)

    holding = None
    current_loc = None
    visited = set()
    steps = 0

    def step(cmd):
        nonlocal steps
        steps += 1
        return env.step(cmd)

    def parse_holding(obs):
        m = re.search(r'You pick up the (.+?)\.', obs, re.I)
        if m:
            return m.group(1).strip()
        return None

    def parse_location(obs):
        m = re.search(r'You arrive at (.+?)\.', obs, re.I)
        if m:
            return m.group(1).strip()
        # If "Nothing happens." then location unchanged
        return None

    def visible_objects(obs):
        objs = []
        # Patterns: "On the X, you see a Y, and a Z."
        # "In it, you see a Y."
        # "you see a Y."
        for m in re.finditer(r'(?:you see|In it, you see)\s+([^.\n]*)', obs, re.I):
            part = m.group(1)
            for item in re.split(r',| and ', part):
                item = item.strip().rstrip('.')
                item = re.sub(r'^(?:a|an|the)\s+', '', item, flags=re.I)
                if item and item.lower() not in ('nothing', 'it'):
                    objs.append(item)
        return objs

    def goto(rec):
        nonlocal current_loc
        fb = step(f'go to {rec}')
        loc = parse_location(fb)
        if loc:
            current_loc = loc
            visited.add(loc.lower())
            return fb
        # Nothing happens -> maybe already there or invalid
        # Check if rec is current location
        if current_loc and current_loc.lower() == rec.lower():
            return fb
        # Try without article
        fb2 = step(f'go to {rec}')
        loc2 = parse_location(fb2)
        if loc2:
            current_loc = loc2
            visited.add(loc2.lower())
        return fb2

    def take_object(loc, o):
        nonlocal holding
        # Try "take X from Y"
        fb = step(f'take {o} from {loc}' if loc else f'take {o}')
        h = parse_holding(fb)
        if h:
            holding = h
            return True
        # Try "take X"
        fb = step(f'take {o}')
        h = parse_holding(fb)
        if h:
            holding = h
            return True
        return False

    # 1. Find the object
    # Check current observation
    objs = visible_objects(get_obs())
    for o in objs:
        if obj_matches(o, obj):
            if take_object(current_loc, o):
                break

    # Search receptacles
    if not holding:
        for rec in receptacles:
            if steps >= 40:
                break
            if rec.lower() in visited:
                continue
            fb = goto(rec)
            # Parse location from fb
            loc = parse_location(fb)
            if loc is None:
                loc = current_loc if current_loc else rec
            # Open if closed
            if 'closed' in fb.lower():
                fb2 = step(f'open {rec}')
                loc2 = parse_location(fb2)
                if loc2:
                    current_loc = loc2
                    loc = loc2
                fb = fb2
            objs = visible_objects(fb)
            for o in objs:
                if obj_matches(o, obj):
                    if take_object(loc, o):
                        break
            if holding:
                break
            # If not found, try opening and looking again
            if 'closed' not in fb.lower() and not holding:
                # maybe open needed
                fb2 = step(f'open {rec}')
                if 'open' in fb2.lower() or 'closed' not in fb2.lower():
                    objs2 = visible_objects(fb2)
                    for o in objs2:
                        if obj_matches(o, obj):
                            if take_object(loc, o):
                                break
                if holding:
                    break

    # 2. Perform action
    if holding and action:
        if action == 'heat':
            fb = goto('microwave 1')
            if 'closed' in fb.lower():
                step('open microwave 1')
            fb = step(f'heat {holding} with microwave 1')
            if 'heat' not in fb.lower() and 'warm' not in fb.lower():
                step(f'heat {holding} with microwave 1')
        elif action == 'clean':
            fb = goto('sinkbasin 1')
            if 'closed' in fb.lower():
                step('open sinkbasin 1')
            fb = step(f'clean {holding} with sinkbasin 1')
            if 'clean' not in fb.lower() and 'wash' not in fb.lower():
                step(f'clean {holding} with sinkbasin 1')
        elif action == 'slice':
            fb = step(f'slice {holding}')

    # 3. Put in final receptacle
    if holding:
        fb = goto(final_rec)
        if 'closed' in fb.lower():
            step(f'open {final_rec}')
        fb = step(f'move {holding} to {final_rec}')
        if 'move' not in fb.lower() and 'put' not in fb.lower():
            step(f'put {holding} in {final_rec}')
        if 'move' in fb.lower() or 'put' in fb.lower():
            holding = None

    return None
